const defaultLimit = 100

type Server struct {
	pool           *pgxpool.Pool
	jobs           *river.Client[pgx.Tx]
	maxUploadBytes int64
}

func NewServer(pool *pgxpool.Pool, jobs *river.Client[pgx.Tx], maxUploadBytes int64) *Server {
	return &Server{pool: pool, jobs: jobs, maxUploadBytes: maxUploadBytes}
}

var _ StrictServerInterface = (*Server)(nil)

func (s *Server) UploadDocument(ctx context.Context, request UploadDocumentRequestObject) (UploadDocumentResponseObject, error) {
	file, err := readFilePart(request.Body, s.maxUploadBytes)
	switch {
	case errors.Is(err, errTooLarge):
		return UploadDocument413JSONResponse{Message: fmt.Sprintf("file is larger than %d MB", s.maxUploadBytes>>20)}, nil
	case err != nil:
		//nolint:nilerr // a bad upload is a 400 response, not a handler failure
		return UploadDocument400JSONResponse{ProblemJSONResponse{Message: err.Error()}}, nil
	}

	sum := sha256.Sum256(file.data)
	var created bool
	var id int64
	err = pgx.BeginFunc(ctx, s.pool, func(tx pgx.Tx) error {
		row, err := dbq.New(tx).UpsertDocument(ctx, dbq.UpsertDocumentParams{
			Sha256:      sum[:],
			Filename:    file.name,
			ContentType: file.contentType,
			Content:     file.data,
		})
		if err != nil {
			return err
		}
		id, created = row.ID, row.Created
		if !created {
			return nil
		}
		// Enqueued in the same transaction: a stored document always has a parse job.
		_, err = s.jobs.InsertTx(ctx, tx, ingest.ParseDocumentArgs{DocumentID: id}, nil)
		return err
	})
	if err != nil {
		return nil, fmt.Errorf("store upload: %w", err)
	}

	doc, err := s.document(ctx, id)
	if err != nil {
		return nil, err
	}
	if created {
		return UploadDocument201JSONResponse(doc), nil
	}
	return UploadDocument200JSONResponse(doc), nil
}

func (s *Server) ListDocuments(ctx context.Context, request ListDocumentsRequestObject) (ListDocumentsResponseObject, error) {
	rows, err := dbq.New(s.pool).ListDocuments(ctx, limit(request.Params.Limit))
	if err != nil {
		return nil, fmt.Errorf("list documents: %w", err)
	}
	docs := make(ListDocuments200JSONResponse, 0, len(rows))
	for _, row := range rows {
		docs = append(docs, toDocument(dbq.GetDocumentRow(row)))
	}
	return docs, nil
}

func (s *Server) GetDocument(ctx context.Context, request GetDocumentRequestObject) (GetDocumentResponseObject, error) {
	doc, err := s.document(ctx, request.Id)
	if errors.Is(err, pgx.ErrNoRows) {
		return GetDocument404JSONResponse{notFound("document", request.Id)}, nil
	}
	if err != nil {
		return nil, err
	}
	return GetDocument200JSONResponse(doc), nil
}

func (s *Server) ReparseDocument(ctx context.Context, request ReparseDocumentRequestObject) (ReparseDocumentResponseObject, error) {
	err := pgx.BeginFunc(ctx, s.pool, func(tx pgx.Tx) error {
		queries := dbq.New(tx)
		if _, err := queries.GetDocument(ctx, request.Id); err != nil {
			return err
		}
		if err := queries.MarkDocumentPending(ctx, request.Id); err != nil {
			return err
		}
		_, err := s.jobs.InsertTx(ctx, tx, ingest.ParseDocumentArgs{DocumentID: request.Id}, nil)
		return err
	})
	if errors.Is(err, pgx.ErrNoRows) {
		return ReparseDocument404JSONResponse{notFound("document", request.Id)}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("queue re-parse: %w", err)
	}
	doc, err := s.document(ctx, request.Id)
	if err != nil {
		return nil, err
	}
	return ReparseDocument202JSONResponse(doc), nil
}

func (s *Server) GetDocumentContent(ctx context.Context, request GetDocumentContentRequestObject) (GetDocumentContentResponseObject, error) {
	row, err := dbq.New(s.pool).GetDocumentContent(ctx, request.Id)
	if errors.Is(err, pgx.ErrNoRows) {
		return GetDocumentContent404JSONResponse{notFound("document", request.Id)}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("get document %d content: %w", request.Id, err)
	}
	// The original comes from the app's own origin: only a PDF may open in place. Anything else
	// downloads, and nosniff stops the browser from guessing its way to HTML.
	disposition := "attachment"
	if row.ContentType == contentTypePDF {
		disposition = "inline"
	}
	disposition = mime.FormatMediaType(disposition, map[string]string{"filename": row.Filename})
	nosniff := "nosniff"
	return GetDocumentContent200AsteriskResponse{
		Body:          bytes.NewReader(row.Content),
		ContentType:   row.ContentType,
		ContentLength: int64(len(row.Content)),
		Headers: GetDocumentContent200ResponseHeaders{
			ContentDisposition:  &disposition,
			XContentTypeOptions: &nosniff,
		},
	}, nil
}

func (s *Server) ListStatements(ctx context.Context, request ListStatementsRequestObject) (ListStatementsResponseObject, error) {
	rows, err := dbq.New(s.pool).ListStatements(ctx, limit(request.Params.Limit))
	if err != nil {
		return nil, fmt.Errorf("list statements: %w", err)
	}
	statements := make(ListStatements200JSONResponse, 0, len(rows))
	for _, row := range rows {
		statements = append(statements, toStatement(row))
	}
	return statements, nil
}

func (s *Server) GetStatement(ctx context.Context, request GetStatementRequestObject) (GetStatementResponseObject, error) {
	row, err := dbq.New(s.pool).GetStatement(ctx, request.Id)
	if errors.Is(err, pgx.ErrNoRows) {
		return GetStatement404JSONResponse{notFound("statement", request.Id)}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("get statement %d: %w", request.Id, err)
	}
	return GetStatement200JSONResponse(toStatement(dbq.ListStatementsRow(row))), nil
}

func (s *Server) ListStatementTransactions(ctx context.Context, request ListStatementTransactionsRequestObject) (ListStatementTransactionsResponseObject, error) {
	queries := dbq.New(s.pool)
	exists, err := queries.StatementExists(ctx, request.Id)
	if err != nil {
		return nil, fmt.Errorf("find statement: %w", err)
	}
	if !exists {
		return ListStatementTransactions404JSONResponse{notFound("statement", request.Id)}, nil
	}
	rows, err := queries.ListTransactions(ctx, request.Id)
	if err != nil {
		return nil, fmt.Errorf("list transactions: %w", err)
	}
	transactions := make(ListStatementTransactions200JSONResponse, 0, len(rows))
	for _, row := range rows {
		transactions = append(transactions, toTransaction(row))
	}
	return transactions, nil
}

func (s *Server) SearchTransactions(ctx context.Context, request SearchTransactionsRequestObject) (SearchTransactionsResponseObject, error) {
	params := request.Params
	filter := dbq.SearchTransactionsParams{
		FromDate:    date(params.From),
		ToDate:      date(params.To),
		ClosingFrom: date(params.ClosingFrom),
		ClosingTo:   date(params.ClosingTo),
		Institution: blankAsNil(params.Institution),
		CardLast4:   blankAsNil(params.Card),
		Overseas:    params.Overseas != nil && *params.Overseas,
		Query:       blankAsNil(params.Q),
		RowLimit:    clamp(params.Limit, defaultLimit, 0, 500),
		RowOffset:   clamp(params.Offset, 0, 0, math.MaxInt32),
	}
	if params.Kind != nil {
		filter.Kinds = make([]string, 0, len(*params.Kind))
		for _, kind := range *params.Kind {
			filter.Kinds = append(filter.Kinds, string(kind))
		}
	}

	queries := dbq.New(s.pool)
	result := TransactionSearch{Items: []Transaction{}}
	if filter.RowLimit > 0 {
		rows, err := queries.SearchTransactions(ctx, filter)
		if err != nil {
			return nil, fmt.Errorf("search transactions: %w", err)
		}
		for _, row := range rows {
			result.Items = append(result.Items, toTransaction(dbq.ListTransactionsRow(row)))
		}
	}
	groups, err := queries.TransactionTotals(ctx, dbq.TransactionTotalsParams{
		Kinds:       filter.Kinds,
		Institution: filter.Institution,
		CardLast4:   filter.CardLast4,
		FromDate:    filter.FromDate,
		ToDate:      filter.ToDate,
		ClosingFrom: filter.ClosingFrom,
		ClosingTo:   filter.ClosingTo,
		Overseas:    filter.Overseas,
		Query:       filter.Query,
	})
	if err != nil {
		return nil, fmt.Errorf("total transactions: %w", err)
	}
	total, byKind, byCard := summarize(groups)
	result.Total, result.Sum = total.count, decimalString(total.amount)
	result.ByKind, result.ByCard = byKind, byCard
	return SearchTransactions200JSONResponse(result), nil
}

func (s *Server) document(ctx context.Context, id int64) (Document, error) {
	row, err := dbq.New(s.pool).GetDocument(ctx, id)
	if err != nil {
		return Document{}, fmt.Errorf("get document %d: %w", id, err)
	}
	return toDocument(row), nil
}

type upload struct {
	name        string
	contentType string
	data        []byte
}

var errTooLarge = errors.New("file too large")

func readFilePart(reader *multipart.Reader, maxBytes int64) (upload, error) {
	for {
		part, err := reader.NextPart()
		if errors.Is(err, io.EOF) {
			return upload{}, errors.New(`form field "file" is missing`)
		}
		if err != nil {
			return upload{}, fmt.Errorf("read form: %w", err)
		}
		if part.FormName() != "file" {
			continue
		}
		data, err := io.ReadAll(io.LimitReader(part, maxBytes+1))
		if err != nil {
			return upload{}, fmt.Errorf("read file: %w", err)
		}
		if int64(len(data)) > maxBytes {
			return upload{}, errTooLarge
		}
		if len(data) == 0 {
			return upload{}, errors.New("file is empty")
		}
		name := filepath.Base(part.FileName())
		return upload{name: name, contentType: contentType(name, data), data: data}, nil
	}
}

const (
	contentTypePDF   = "application/pdf"
	contentTypeEmail = "message/rfc822"
	contentTypeOther = "application/octet-stream"
)

// contentType is decided from the bytes and the file extension only, never from what the browser
// declares: the original is served back from the app's origin, so a stored "text/html" or
// "image/svg+xml" would run there. The parser reads only PDFs and e-mails anyway.
func contentType(name string, data []byte) string {
	switch {
	case bytes.HasPrefix(data, []byte("%PDF")):
		return contentTypePDF
	case strings.EqualFold(filepath.Ext(name), ".eml"):
		return contentTypeEmail
	default:
		return contentTypeOther
	}
}

func limit(requested *Limit) int32 {
	if requested == nil {
		return defaultLimit
	}
	// The spec allows 1-500, but the generated handlers do not enforce it.
	return int32(min(max(*requested, 1), 500)) //nolint:gosec // clamped above
}

// clamp applies a query parameter's default and range, which the generated handlers do not enforce.
func clamp(requested *int, fallback, lo, hi int) int32 {
	if requested == nil {
		return int32(fallback) //nolint:gosec // a small constant
	}
	return int32(min(max(*requested, lo), hi)) //nolint:gosec // clamped to hi, at most MaxInt32
}

func date(d *openapi_types.Date) pgtype.Date {
	if d == nil {
		return pgtype.Date{}
	}
	return pgtype.Date{Time: d.Time, Valid: true}
}

func blankAsNil(s *string) *string {
	if s == nil || strings.TrimSpace(*s) == "" {
		return nil
	}
	trimmed := strings.TrimSpace(*s)
	return &trimmed
}

func notFound(what string, id int64) ProblemJSONResponse {
	return ProblemJSONResponse{Message: fmt.Sprintf("%s %d not found", what, id)}
}
